/**
 * The admin API client (openapi-fetch over admin/src/schema.d.ts, generated by
 * `npm run admin:api`). The admin cookie authenticates; changes carry the CSRF
 * token. A 401 anywhere except the sign-in steps sends the admin back to sign-in.
 */
import createClient, { type Middleware } from "openapi-fetch";
import { ask } from "./nia/changeGate";
import type { components, paths } from "./schema";

export type Schemas = components["schemas"];

export interface ErrorEnvelope {
  code: string;
  message: string;
  fields?: { field: string; message: string }[];
}

export class ApiError extends Error {
  status: number;
  code: string;
  constructor(status: number, envelope: ErrorEnvelope) {
    // A form error names the field and the reason ("about: at most 2000 characters"), not only "check the fields".
    const fields = (envelope.fields ?? []).map((f) => `${f.field.replace(/_/g, " ") || "value"}: ${f.message}`).join("; ");
    super((envelope.message || `Request failed (${status})`) + (fields ? ` — ${fields}` : ""));
    this.status = status;
    this.code = envelope.code || "HTTP_ERROR";
  }
}

let csrfToken = "";
export function setCsrfToken(token: string): void {
  csrfToken = token;
}

const listeners = new Set<() => void>();
export function onSignedOut(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

const middleware: Middleware = {
  async onRequest({ request }) {
    // A change that follows one of Nia's actions waits for your Allow (nia/changeGate.ts).
    if (!(await ask(request.method, request.url))) throw new ApiError(409, { code: "NIA_CHANGE_CANCELLED", message: "You cancelled Nia's change. Nothing was saved." });
    if (!["GET", "HEAD", "OPTIONS"].includes(request.method) && csrfToken) request.headers.set("X-CSRF-Token", csrfToken);
    return request;
  },
  async onResponse({ response, request }) {
    if (response.status === 401 && !request.url.includes("/admin-api/auth/")) listeners.forEach((l) => l());
    return response;
  },
};

export const api = createClient<paths>({ baseUrl: "", credentials: "same-origin" });
api.use(middleware);

export function unwrap<T>(result: { data?: T; error?: unknown; response: Response }): T {
  if (result.response.ok && result.data !== undefined) return result.data;
  const envelope = (result.error as { error?: ErrorEnvelope } | undefined)?.error ?? { code: "HTTP_ERROR", message: `Request failed (${result.response.status})` };
  throw new ApiError(result.response.status, envelope);
}

export function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : "Something went wrong.";
}

/** One admin request by address, sent by this page with the admin's own sign-in. Used only for
 * a change Nia proposed and the owner just approved on its card (team/Approvals.tsx), after the
 * server checked it. */
export async function sendAsSignedIn(method: string, path: string, query: Record<string, unknown>, body: unknown): Promise<{ status: number; answer: unknown }> {
  const search = new URLSearchParams(Object.entries(query).map(([k, v]) => [k, String(v)])).toString();
  if (!(await ask(method, path))) throw new ApiError(409, { code: "NIA_CHANGE_CANCELLED", message: "You cancelled Nia's change. Nothing was saved." });
  const response = await fetch(path + (search ? `?${search}` : ""), {
    method,
    credentials: "same-origin",
    headers: { "Content-Type": "application/json", Accept: "application/json", ...(csrfToken ? { "X-CSRF-Token": csrfToken } : {}) },
    body: body === null || body === undefined ? undefined : JSON.stringify(body),
  });
  if (response.status === 401) listeners.forEach((l) => l());
  let answer: unknown = null;
  try {
    answer = await response.json();
  } catch {
    answer = null;
  }
  return { status: response.status, answer };
}
